import math

def ar1_moments(c, phi, sigma2):
    if abs(phi) >= 1:
        raise ValueError("need |phi| < 1")
    mean = c / (1 - phi)
    var = sigma2 / (1 - phi ** 2)
    return mean, var, phi, phi ** 2

